	t.Parallel()
	site := siteFile(t, "style.css")
	own, err := os.ReadFile(filepath.Join("report.css"))
	if err != nil {
		t.Fatalf("read report.css: %v", err)
	}

	shared := []string{
		"--paper", "--ink", "--ink-2", "--rule",
		"--corroborated", "--uncorroborated", "--unverifiable", "--focus",
	}
	reportVals := firstTokenValues(string(own), shared)
	siteVals := firstTokenValues(site, shared)

	for _, tok := range shared {
		r, ok := reportVals[tok]
		if !ok {
			t.Errorf("report.css does not define %s", tok)
			continue
		}
		s, ok := siteVals[tok]
		if !ok {
			t.Errorf("site/style.css does not define %s, so the surfaces can disagree about it", tok)
			continue
		}
		if !strings.EqualFold(r, s) {
			t.Errorf("%s is %s in the report and %s on the page; the two surfaces must agree", tok, r, s)
		}
	}
}

// firstTokenValues reads the first declaration of each token, which is the
// light-scheme value in both files.
func firstTokenValues(css string, tokens []string) map[string]string {
	out := map[string]string{}
	for _, tok := range tokens {
		re := regexp.MustCompile(regexp.QuoteMeta(tok) + `\s*:\s*([^;]+);`)
		if m := re.FindStringSubmatch(css); m != nil {
			out[tok] = strings.TrimSpace(m[1])
		}
	}
	return out
}

